def period_key(kind: str, local: datetime) -> str:
    if kind == "daily":
        return local.date().isoformat()
    if kind == "weekly":
        return f"{local.year}-W{local.isocalendar()[1]:02d}"
    if kind == "monthly":
        return f"{local.year}-{local.month:02d}"
    if kind == "yearly":
        return str(local.year)
    raise ValueError(kind)
