def make_plan(s: BackupSet) -> dict:
    backups, ignored, broken = [], [], []
    for name in s.files:
        b = parse_name(name, s.prefix, s.zone)
        if b is None and not name.startswith(f"{s.prefix}-"):
            ignored.append(name)
        elif b is None:
            broken.append(name)
        else:
            backups.append(b)
    reasons = select(s.policy, backups, s.pins, s.now)
    order = sorted(backups, key=lambda b: b.name, reverse=True)
    keep = [{"name": b.name, "at": iso(b.at), "reasons": reasons[b.name]} for b in order if reasons[b.name]]
    prune = [b.name for b in order if not reasons[b.name]] + sorted(broken)
